SELECT jsonb_build_object('capturedAt',clock_timestamp(),'tables',jsonb_build_object('module_catalog',(SELECT coalesce(jsonb_agg(to_jsonb(r) ORDER BY key),'[]'::jsonb) FROM (SELECT key,name,description,category,sandbox_available,definition FROM public.module_catalog WHERE key IN ('crypto_exchange','website','merchant_api','crypto_payments','crypto_card','staking','earn','dex','telegram_bot','telegram_mini_app','whatsapp_bot','ios_app','android_app','crypto_engine','rpc_nodes','cloud_mining','articles')) r),'entitlement_definitions',(SELECT coalesce(jsonb_agg(to_jsonb(r) ORDER BY key),'[]'::jsonb) FROM (SELECT key,label,kind,value_type FROM public.entitlement_definitions WHERE key IN ('crypto_exchange','swap','convert','buy','sell','website','merchant_api','api_keys','webhooks','crypto_payments','crypto_card','staking','earn','dex','telegram_bot','telegram_mini_app','whatsapp_bot','ios_app','android_app','crypto_engine','rpc_nodes','cloud_mining','articles','max_supported_assets','max_supported_networks','max_payment_methods','max_staff','max_api_keys','max_webhooks','max_monthly_transactions','max_monthly_volume')) r),'asset_catalog',(SELECT coalesce(jsonb_agg(to_jsonb(r) ORDER BY id),'[]'::jsonb) FROM (SELECT id,symbol,name FROM public.asset_catalog WHERE id IN ('btc','eth','usdt','sol','bnb')) r),'network_catalog',(SELECT coalesce(jsonb_agg(to_jsonb(r) ORDER BY id),'[]'::jsonb) FROM (SELECT id,name,testnet FROM public.network_catalog WHERE id IN ('bitcoin-testnet','ethereum-sepolia','solana-devnet','bsc-testnet','tron-nile')) r),'asset_network_catalog',(SELECT coalesce(jsonb_agg(to_jsonb(r) ORDER BY id),'[]'::jsonb) FROM (SELECT id,asset_id,network_id FROM public.asset_network_catalog WHERE id IN ('btc:bitcoin-testnet','eth:ethereum-sepolia','usdt:ethereum-sepolia','sol:solana-devnet','bnb:bsc-testnet','usdt:bsc-testnet','usdt:tron-nile')) r),'landing_products',(SELECT coalesce(jsonb_agg(to_jsonb(r) ORDER BY key),'[]'::jsonb) FROM (SELECT key,visible,name,description,icon,starting_price::text AS starting_price,setup_fee::text AS setup_fee,currency,billing_period,status,cta_label,display_order FROM public.landing_products WHERE key IN ('crypto_exchange','crypto_payments','crypto_engine','ios_app','android_app','crypto_card','staking','earn','dex','articles','telegram_bot','telegram_mini_app','whatsapp_bot','rpc_nodes','cloud_mining')) r))) AS recovery_snapshot;
